pub fn titles(
    input: &str,
    max_bytes: usize,
) -> Result<Vec<String>, String> {
    if input.len() > max_bytes {
        return Err("too large".to_owned());
    }
    let mut out = Vec::new();
    for line in input.lines() {
        let value = line.trim();
        if value.chars().count() > 80 {
            return Err("title too long".to_owned());
        }
        if !value.is_empty() {
            out.push(value.to_owned());
        }
    }
    Ok(out)
}

fn main() {
    assert_eq!(
        titles(
            " one

 two 
",
            100
        ),
        Ok(vec!["one".to_owned(), "two".to_owned()]),
        "case 1"
    );
    assert_eq!(titles("", 0), Ok(vec![]), "case 2");
    assert_eq!(titles("🦀", 3), Err("too large".to_owned()), "case 3");
    assert_eq!(
        titles(&"x".repeat(81), 100),
        Err("title too long".to_owned()),
        "case 4"
    );
    assert_eq!(titles("🦀", 4), Ok(vec!["🦀".to_owned()]), "case 5");
    println!("worked example passed");
}

